# frozen_string_literal: true

# Core namespace for the CDD Ruby compiler and OpenAPI toolchain.
module Cdd
  # Shared Ripper token scanning utilities used across CDD parsers.
  module TokenScanner
    # HTTP method verbs supported in Sinatra and OpenAPI 3.2.0 route definitions.
    SINATRA_HTTP_VERBS = %w[get post put delete patch options head trace query].freeze

    # Preceding token types or values that disqualify an identifier from being a top-level Sinatra route.
    DISQUALIFYING_PREV_TYPES = %i[on_symbeg on_period on_ident].freeze

    # Internal scaffolding class names generated by CDD that are not OpenAPI domain models.
    SCAFFOLDING_CLASSES = %w[
      CliParser Factory DatabaseConnection ClientSdk ClientSdkMcpAdapter
      ClientSdkAuthAdapter WorkflowsOrchestrator ArazzoWorkflowsTest
    ].freeze

    # Checks whether a class name is an internal scaffolding or DAO class.
    #
    # @param name [String] the Ruby class name
    # @return [Boolean] true if the class is internal scaffolding
    def self.scaffolding_class?(name)
      SCAFFOLDING_CLASSES.include?(name) || name.end_with?('Dao')
    end

    # Normalizes an OpenAPI operationId or synthesizes a Ruby method name from HTTP method and path.
    #
    # @param method [String] HTTP verb
    # @param path [String] OpenAPI path string
    # @param details [Hash] OpenAPI operation hash
    # @param collapse [Boolean] whether to collapse repeated/edge underscores in fallback operationIds
    # @return [String] valid Ruby method identifier for the operation
    def self.operation_id_for(method, path, details = {}, collapse: true)
      raw_id = details['operationId']
      return raw_id.to_s.gsub(/[^a-zA-Z0-9_]/, '_') if raw_id && !raw_id.to_s.empty?

      sanitized = path.gsub(/[^a-zA-Z0-9]/, '_')
      sanitized = sanitized.gsub(/_+/, '_').sub(/\A_/, '').sub(/_\z/, '') if collapse
      "#{method}_#{sanitized}"
    end

    # Escapes a string into a safe single-quoted Ruby literal (`'...'`).
    #
    # @param str [String] raw string
    # @return [String] single-quoted Ruby string literal
    def self.single_quote_literal(str)
      "'#{str.to_s.gsub('\\', '\\\\\\\\').gsub("'", "\\\\'")}'"
    end

    # Converts a snake_case or lowercase schema/table name into a PascalCase Ruby class name.
    #
    # @param name [String, Symbol] raw name
    # @return [String] classified Ruby class name
    def self.classify_name(name)
      name.to_s.sub(/\A[a-z]/, &:upcase)
    end

    # Pluralizes a lowercase or PascalCase noun into a lowercase SQL table name.
    #
    # @param word [String, Symbol] singular noun or schema name
    # @return [String] lowercase pluralized table name
    def self.pluralize(word)
      down = word.to_s.downcase
      if down.end_with?('y') && %w[ay ey iy oy uy].none? { |v| down.end_with?(v) }
        "#{down[0...-1]}ies"
      elsif %w[s x z ch sh].any? { |suf| down.end_with?(suf) }
        "#{down}es"
      else
        "#{down}s"
      end
    end

    # Extracts the first media type schema from an operation's `requestBody` hash.
    #
    # @param op [Hash] OpenAPI operation hash
    # @return [Hash, nil] request body schema hash or nil
    def self.first_request_body_schema(op)
      content = op.dig('requestBody', 'content')
      return nil unless content.is_a?(Hash) && !content.empty?

      content.values.first['schema']
    end

    # Returns candidate lowercase singular schema names for a plural path segment.
    #
    # @param word [String, Symbol] path resource segment
    # @return [Array<String>] candidate singular forms
    def self.singularize_candidates(word)
      down = word.to_s.downcase
      [
        down,
        down.sub(/ies\z/, 'y'),
        down.sub(/es\z/, ''),
        down.sub(/s\z/, '')
      ].uniq
    end

    # Maps a schema's properties into `[column_name, active_record_type]` pairs (excluding `'id'`).
    #
    # @param schema [Hash] OpenAPI schema definition hash
    # @return [Array<Array(String, String)>] list of `[prop_name, column_type]` pairs
    def self.table_columns_for_schema(schema)
      (schema['properties'] || {}).filter_map do |prop_name, prop_details|
        next nil if prop_name == 'id'

        col_type = case prop_details['type']
                   when 'integer' then 'integer'
                   when 'boolean' then 'boolean'
                   else 'string'
                   end
        [prop_name, col_type]
      end
    end

    # Builds a sample Ruby Hash literal string from an OpenAPI schema's properties or sensible defaults.
    #
    # @param schema [Hash, nil] OpenAPI schema hash
    # @param symbol_keys [Boolean] whether to format keys as Ruby symbols (`id: 1`) instead of strings (`'id' => 1`)
    # @return [String] Ruby Hash literal expression
    def self.sample_body_hash_literal(schema = nil, symbol_keys: false)
      props = schema.is_a?(Hash) ? schema['properties'] : nil
      if props.is_a?(Hash) && !props.empty?
        pairs = props.map do |k, v|
          val = case v['type']
                when 'integer', 'number' then '1'
                when 'boolean' then 'true'
                when 'array' then "['http://example.com']"
                else "'test'"
                end
          symbol_keys ? "#{k}: #{val}" : "#{single_quote_literal(k)} => #{val}"
        end
        "{ #{pairs.join(', ')} }"
      elsif symbol_keys
        "{ id: 1, name: 'test', photoUrls: ['http://example.com'], status: 'available' }"
      else
        "{ 'id' => 1, 'name' => 'doggie', 'photoUrls' => ['http://example.com'], 'status' => 'available' }"
      end
    end

    # Returns a sample Ruby literal string for an OpenAPI parameter or request body in generated tests.
    #
    # @param param [Hash] parameter hash with `'name'`, `'in'`, and optional `'schema'`
    # @return [String] Ruby literal expression
    def self.sample_param_value(param)
      return '1' if param.dig('schema', 'type') == 'integer' || param['type'] == 'integer'

      if param['in'] == 'body'
        ref = param.dig('schema', '$ref').to_s
        if ref.include?('Order')
          "{ 'id' => 1, 'petId' => 1, 'quantity' => 1, 'status' => 'placed', 'complete' => true }"
        elsif param.dig('schema', 'type') == 'array' || param['type'] == 'array'
          "[{ 'id' => 1, 'username' => 'user1' }]"
        elsif ref.include?('User')
          "{ 'id' => 1, 'username' => 'user1' }"
        else
          sample_body_hash_literal(param['schema'])
        end
      else
        param['name'] == 'status' ? "'available'" : "'test_#{param['name']}'"
      end
    end

    # Parses a `@schema_one_of` or `@schema_any_of` comment body into an OpenAPI composition schema hash.
    #
    # @param composition_key [String] either 'oneOf' or 'anyOf'
    # @param rest [String] the remainder of the docstring comment after the schema name
    # @return [Hash{String => Object}] the constructed OpenAPI schema definition
    def self.parse_composition_schema(composition_key, rest)
      parts = rest.strip.split(/\s+/)
      refs_part = parts.shift || ''
      refs = refs_part.split(',').map { |r| { '$ref' => "#/components/schemas/#{r.strip}" } }
      schema = { composition_key => refs }

      discriminator = parse_discriminator_options(parts)
      schema['discriminator'] = discriminator if discriminator
      schema
    end

    # Parses discriminator options (`discriminator:`, `mapping:`, `defaultMapping:`) from token parts.
    #
    # @param parts [Array<String>] space-separated key:value tokens
    # @return [Hash{String => Object}, nil] discriminator hash or nil if none present
    def self.parse_discriminator_options(parts)
      discriminator = nil
      parts.each do |part|
        if part.start_with?('discriminator:')
          discriminator ||= {}
          discriminator['propertyName'] = part.split(':', 2).last
        elsif part.start_with?('mapping:')
          discriminator ||= {}
          mapping = {}
          part.split(':', 2).last.split(',').each do |pair|
            k, v = pair.split(':')
            mapping[k] = "#/components/schemas/#{v}"
          end
          discriminator['mapping'] = mapping
        elsif part.start_with?('defaultMapping:')
          discriminator ||= {}
          discriminator['defaultMapping'] = "#/components/schemas/#{part.split(':', 2).last}"
        end
      end
      discriminator
    end

    # Parses Sinatra-style route declarations from a Ripper token stream into the IR.
    #
    # @param tokens [Array<Array>] Ripper lexed token stream
    # @param ir [Cdd::IR] Intermediate Representation to populate
    # @return [void]
    def self.parse_sinatra_routes(tokens, ir)
      prev_non_space_type = nil
      tokens.each_with_index do |token, idx|
        if token[1] == :on_ident && SINATRA_HTTP_VERBS.include?(token[2].downcase) &&
           !DISQUALIFYING_PREV_TYPES.include?(prev_non_space_type)
          path = extract_route_path_literal(tokens, idx)
          register_sinatra_route(ir, token[2].downcase, path) if path&.start_with?('/') && !path.start_with?('/mcp/')
        end
        prev_non_space_type = token[1] unless token[1] == :on_sp
      end
    end

    # Extracts the string literal path argument following a route verb token.
    #
    # @param tokens [Array<Array>] Ripper lexed token stream
    # @param idx [Integer] route verb token index
    # @return [String, nil] the route path string or nil if not a route literal
    def self.extract_route_path_literal(tokens, idx)
      cursor = skip_spaces(tokens, idx + 1)
      nxt = tokens[cursor]
      cursor = skip_spaces(tokens, cursor + 1) if nxt && nxt[1] == :on_lparen
      target = tokens[cursor]
      return nil unless target && %i[on_tstring_beg on_tstring_content].include?(target[1])

      path_token = tokens[cursor..(cursor + 2)].find { |t| t[1] == :on_tstring_content }
      path_token ? path_token[2] : nil
    end

    # Advances the token index past any `:on_sp` whitespace tokens.
    #
    # @param tokens [Array<Array>] Ripper lexed token stream
    # @param start_idx [Integer] starting index
    # @return [Integer] index of the first non-space token
    def self.skip_spaces(tokens, start_idx)
      cursor = start_idx
      cursor += 1 while cursor < tokens.size && tokens[cursor][1] == :on_sp
      cursor
    end

    # Registers an extracted Sinatra route and its `:param` path parameters in the IR.
    #
    # @param ir [Cdd::IR] Intermediate Representation
    # @param method [String] lowercase HTTP method
    # @param path [String] Sinatra route path
    # @return [void]
    def self.register_sinatra_route(ir, method, path)
      openapi_path = path.gsub(/:([a-zA-Z0-9_]+)/, '{\1}')
      ir.routes |= ["#{method.upcase} #{openapi_path}"]
      ir.openapi_spec['paths'] ||= {}
      ir.openapi_spec['paths'][openapi_path] ||= {}
      ir.openapi_spec['paths'][openapi_path][method] ||= {
        'responses' => { '200' => { 'description' => 'OK' } }
      }

      params = (ir.openapi_spec['paths'][openapi_path][method]['parameters'] ||= [])
      path.scan(/:([a-zA-Z0-9_]+)/).flatten.each do |param_name|
        next if params.any? { |p| p['name'] == param_name }

        params << {
          'name' => param_name,
          'in' => 'path',
          'required' => true,
          'schema' => { 'type' => 'string' }
        }
      end
    end
  end
end
